code.after:
class BankAccount {
  private balance = 100;
  private mutex = new Mutex(); // only one thread inside at a time

  async withdraw(amount: number): Promise<boolean> {
    return this.mutex.runExclusive(() => {
      // No other thread can be inside ANY method on this object right now
      if (this.balance >= amount) {
        this.balance -= amount;
        return true;
      }
      return false;
    });
  }

  async deposit(amount: number): Promise<void> {
    return this.mutex.runExclusive(() => {
      this.balance += amount;
    });
  }
}
